mapper.sql:
SELECT T1.ENTRUST_ID, '01' PLEDGE_FINPROD, T1.ENTRUST_AMT PLEDGE_AMT FROM ETR_ENTRUST T1 LEFT JOIN ETR_PLEDGE T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN(
) T3 ON T2.FINPROD_ID = T3.FINPROD_ID LEFT JOIN ETR_ENTRUST_ADD T4 ON T1.ENTRUST_ID = T4.ENTRUST_ID LEFT JOIN ETR_DISTRIBUTE T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID WHERE T4.ASSET_TYPE = #{PINAN_ASSET_TYPE_F07} AND PLEDGE_FINPROD IS NULL AND T5.TRADER = #{user}
UNION ALL
SELECT T1.ENTRUST_ID, '02' PLEDGE_FINPROD, LEAST(T1.ENTRUST_AMT, NVL(T2.PLEDGE_AMT, 0)) PLEDGE_AMT FROM ETR_ENTRUST T1 LEFT JOIN ETR_PLEDGE T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN(
) T3 ON T2.FINPROD_ID = T3.FINPROD_ID LEFT JOIN ETR_ENTRUST_ADD T4 ON T1.ENTRUST_ID = T4.ENTRUST_ID LEFT JOIN ETR_DISTRIBUTE T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID WHERE T4.ASSET_TYPE = #{PINAN_ASSET_TYPE_F07} AND PLEDGE_FINPROD = '02' AND T5.TRADER = #{user}
UNION ALL
SELECT ENTRUST_ID, PLEDGE_FINPROD, LEAST(PLEDGE_AMT03, ENTRUST_AMT - NVL(PLEDGE_AMT02, 0)) PLEDGE_AMT FROM( SELECT T1.ENTRUST_ID, T1.ENTRUST_AMT, '03' PLEDGE_FINPROD, LEAST(T1.ENTRUST_AMT, NVL(T2.PLEDGE_AMT, 0)) PLEDGE_AMT03, T6.PLEDGE_AMT02 FROM ETR_ENTRUST T1 LEFT JOIN ETR_PLEDGE T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN(
) T3 ON T2.FINPROD_ID = T3.FINPROD_ID LEFT JOIN ETR_ENTRUST_ADD T4 ON T1.ENTRUST_ID = T4.ENTRUST_ID LEFT JOIN ETR_DISTRIBUTE T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN( SELECT T1.ENTRUST_ID, '02' PLEDGE_FINPROD02, SUM(LEAST(T1.ENTRUST_AMT, NVL(T2.PLEDGE_AMT, 0))) PLEDGE_AMT02 FROM ETR_ENTRUST T1 LEFT JOIN ETR_PLEDGE T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN(
) T3 ON T2.FINPROD_ID = T3.FINPROD_ID LEFT JOIN ETR_ENTRUST_ADD T4 ON T1.ENTRUST_ID = T4.ENTRUST_ID LEFT JOIN ETR_DISTRIBUTE T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID WHERE T4.ASSET_TYPE = #{PINAN_ASSET_TYPE_F07} AND PLEDGE_FINPROD = '02' AND T5.TRADER = #{user} GROUP BY T1.ENTRUST_ID ) T6 ON T1.ENTRUST_ID = T6.ENTRUST_ID WHERE T4.ASSET_TYPE = #{PINAN_ASSET_TYPE_F07} AND PLEDGE_FINPROD = '03' AND T5.TRADER = #{user})
UNION ALL
SELECT ENTRUST_ID, PLEDGE_FINPROD, LEAST(PLEDGE_AMT04, ENTRUST_AMT - NVL(PLEDGE_AMT03, 0) - NVL(PLEDGE_AMT02, 0)) PLEDGE_AMT FROM( SELECT T1.ENTRUST_ID, T1.ENTRUST_AMT, '04' PLEDGE_FINPROD, LEAST(T1.ENTRUST_AMT, NVL(T2.PLEDGE_AMT, 0)) PLEDGE_AMT04, T6.PLEDGE_AMT02, T7.PLEDGE_AMT03 FROM ETR_ENTRUST T1 LEFT JOIN ETR_PLEDGE T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN(
) T3 ON T2.FINPROD_ID = T3.FINPROD_ID LEFT JOIN ETR_ENTRUST_ADD T4 ON T1.ENTRUST_ID = T4.ENTRUST_ID LEFT JOIN ETR_DISTRIBUTE T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN( SELECT T1.ENTRUST_ID, '02' PLEDGE_FINPROD02, SUM(LEAST(T1.ENTRUST_AMT, NVL(T2.PLEDGE_AMT, 0))) PLEDGE_AMT02 FROM ETR_ENTRUST T1 LEFT JOIN ETR_PLEDGE T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN(
) T3 ON T2.FINPROD_ID = T3.FINPROD_ID LEFT JOIN ETR_ENTRUST_ADD T4 ON T1.ENTRUST_ID = T4.ENTRUST_ID LEFT JOIN ETR_DISTRIBUTE T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID WHERE T4.ASSET_TYPE = #{PINAN_ASSET_TYPE_F07} AND PLEDGE_FINPROD = '02' AND T5.TRADER = #{user} GROUP BY T1.ENTRUST_ID ) T6 ON T6.ENTRUST_ID = T1.ENTRUST_ID LEFT JOIN( SELECT T1.ENTRUST_ID, '03' PLEDGE_FINPROD03, SUM(LEAST(T1.ENTRUST_AMT, NVL(T2.PLEDGE_AMT, 0))) PLEDGE_AMT03 FROM ETR_ENTRUST T1 LEFT JOIN ETR_PLEDGE T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN(
) T3 ON T2.FINPROD_ID = T3.FINPROD_ID LEFT JOIN ETR_ENTRUST_ADD T4 ON T1.ENTRUST_ID = T4.ENTRUST_ID LEFT JOIN ETR_DISTRIBUTE T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID WHERE T4.ASSET_TYPE = #{PINAN_ASSET_TYPE_F07} AND PLEDGE_FINPROD = '03' AND T5.TRADER = #{user} GROUP BY T1.ENTRUST_ID ) T7 ON T7.ENTRUST_ID = T1.ENTRUST_ID WHERE T4.ASSET_TYPE = #{PINAN_ASSET_TYPE_F07} AND PLEDGE_FINPROD = '04' AND T5.TRADER = #{user})

mapper.select:
SELECT FIN_PRODUCT.FINPROD_ID finprodId,/* add by songyawei */ FINPROD_MARKET_ID code, FINPROD_ABBR shortName FROM FIN_PRODUCT LEFT JOIN FIN_PRODUCT_TYPE ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID
(FINPROD_MARKET_ID like CONCAT(CONCAT('%', #{finprodMarketId,jdbcType=VARCHAR}),'%') OR FINPROD_ABBR like CONCAT(CONCAT('%', #{finprodMarketId,jdbcType=VARCHAR}),'%'))
AND FIN_PRODUCT_TYPE.TYPE_8 = #{assetType,jdbcType=VARCHAR}

SELECT T1.CCY ccy, T1.CHL_ID chlId, T3.FINPROD_ID finprodId, T3.FINPROD_MARKET_ID finprodMarketId,
T2.ASSET_TYPE, T3.FINPROD_ABBR finprodName, T1.TRADE_MARKET tradeMarket, DECODE(T2.ASSET_TYPE, #{PINAN_ASSET_TYPE_F01}, SUM(NVL(T1.ENTRUST_NUM * 100, 0) - NVL(T4.FINISHED_AMT * 100, 0)), #{PINAN_ASSET_TYPE_F10}, SUM(NVL(T1.ENTRUST_NUM * 100, 0) - NVL(T4.FINISHED_AMT * 100, 0)), SUM(NVL(T1.ENTRUST_AMT, T1.ENTRUST_NUM) - NVL(T4.FINISHED_AMT, 0))) unfinishedAmt, T1.PS ps, T1.TRADE_PLAT tradePlat, T11.TYPE_6 type6, T11.TYPE_7 type7, NVL2(T2.SETTLE_SPREED, CONCAT('0',T2.SETTLE_SPREED+1), NULL) settleSpeed
T3.FINPROD_ABBR finprodName, SUM(NVL(T1.ENTRUST_AMT, 0)) entrustAmt, DECODE(T2.ASSET_TYPE, #{PINAN_ASSET_TYPE_F01}, SUM(NVL(T1.ENTRUST_NUM * 100, 0) - NVL(T4.FINISHED_AMT * 100, 0)), #{PINAN_ASSET_TYPE_F10}, SUM(NVL(T1.ENTRUST_NUM * 100, 0) - NVL(T4.FINISHED_AMT * 100, 0)), SUM(NVL(T1.ENTRUST_AMT, T1.ENTRUST_NUM) - NVL(T4.FINISHED_AMT, 0))) unfinishedAmt, T1.PS ps, T11.TYPE_6 type6, T10.FINPROD_ABBR chlName
T1.TRADE_MARKET tradeMarket, T1.PS ps, T2.TERM_DAYS termDays, NVL2(T2.SETTLE_SPREED, CONCAT('0',T2.SETTLE_SPREED+1), NULL) settleSpeed
FROM ETR_ENTRUST T1 LEFT JOIN ETR_ENTRUST_ADD T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN(SELECT ENTRUST_ID,SUM(FINISH_AMT) AS FINISHED_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T4 ON T1.ENTRUST_ID = T4.ENTRUST_ID LEFT JOIN ETR_DISTRIBUTE T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID
LEFT JOIN FIN_PRODUCT_TYPE T11 ON T1.FINPROD_ID = T11.FINPROD_ID
LEFT JOIN FIN_PRODUCT_TYPE T11 ON T1.FINPROD_ID = T11.FINPROD_ID
LEFT JOIN FIN_PRODUCT T10 ON T1.CHL_ID = T10.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T11 ON T1.FINPROD_ID = T11.FINPROD_ID
T1.ENTRUST_CLASS= #{ENTRUST_CLASS_01} AND T5.TRADER = #{user} AND T1.ENTRUST_STATUS = #{entrustStatus} AND (T2.ENTRUST_CREATE_SOURCE is null or T2.ENTRUST_CREATE_SOURCE != '02')
AND (T1.PS = #{PS_T01} OR T1.PS = #{PS_T02} OR T1.PS = #{PS_T03})
AND T2.ASSET_TYPE = #{assetType}
AND DECODE(T15.PLEDGE_FINPROD, NULL, '01', T15.PLEDGE_FINPROD) = #{pledgeFinprod}
AND (T3.FINPROD_ID LIKE CONCAT('%',CONCAT(#{finprodId},'%')) OR T3.FINPROD_MARKET_ID LIKE CONCAT('%',CONCAT(#{finprodId},'%')) OR T3.FINPROD_ABBR LIKE CONCAT('%',CONCAT(#{finprodId},'%')))
AND T11.TYPE_6 IN(
#{item}
)
AND T11.TYPE_7 IN(
#{item}
)
AND T1.PS = #{ps}
AND T2.BUSI_PS = #{busiPs}
AND T1.TRADE_MARKET = #{tradeMarket}
AND T1.TRADE_PLAT = #{tradePlat}
AND T2.DEAL_MODE = #{dealMode}
AND T7.BOARD = #{board}
AND T2.PURCH_MODLE = #{purchModle}
AND T2.PURCH_TYPE = #{purchType}
AND T2.SEC_ACCT_ID = #{secAcctId}
AND T2.ASSET_TYPE1 = #{repoType}
AND T2.ASSET_TYPE1 = #{bankLendingType}
GROUP BY T1.CCY ,T1.CHL_ID /* add by songyawei */
, T2.ASSET_TYPE, T3.FINPROD_ID, T3.FINPROD_MARKET_ID, T3.FINPROD_ABBR, T1.TRADE_MARKET
, T1.PS, T1.TRADE_PLAT, T2.SETTLE_SPREED, T11.TYPE_6, T11.TYPE_7
, T1.PS, T11.TYPE_6, T10.FINPROD_ABBR
, T1.PS, T2.TERM_DAYS, T2.SETTLE_SPREED

SELECT T1.CCY ccy, T1.CHL_ID chlId, /* add by songyawei */
T3.FINPROD_ID finprodId, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_ABBR finprodName, T1.TRADE_MARKET tradeMarket,
T17.FINPROD_ABBR chlName, T2.PURCH_MODLE purchModle, T2.PURCH_TYPE purchType, T2.SEC_ACCT_ID secAcctId, T8.SEC_ACCT_NAME secAcctName,
T17.FINPROD_ABBR chlName, T2.SEC_ACCT_ID secAcctId, T8.SEC_ACCT_NAME secAcctName, T13.FINPROD_MARKET_ID shareId, T13.FINPROD_NAME shareName, T12.CON_SHARE_ID conShareId, SUM(T1.ENTRUST_NUM*100) stocketrPriceTotal, SUM(T2.EXP_CON_VALUE) expConValue,
T1.PS ps, T17.FINPROD_ABBR chlName, T2.SEC_ACCT_ID secAcctId, T11.TYPE_6 type6, T8.SEC_ACCT_NAME secAcctName,
T1.PS ps, T11.TYPE_6 type6,
T10.FINPROD_ABBR chlName,
T1.PS ps, T11.TYPE_6 type6,
T1.PS ps, T1.TRADE_MARKET tradeMarket, T2.ASSET_TYPE1 type6, T2.TERM_DAYS termDays, NVL2(T2.SETTLE_SPREED, CONCAT('0',T2.SETTLE_SPREED+1), NULL) settleSpeed, T15.PLEDGE_FINPROD pledgeFinprod,
T2.BUSI_PS ps, T1.CALENDAR_ID calendarId, T14.CALENDAR_NAME calendarName, T2.ASSET_TYPE1 type6, T2.TERM_DAYS termDays,
T1.PS ps, T17.FINPROD_ABBR chlName, T7.BOARD board, T2.SEC_ACCT_ID secAcctId, T8.SEC_ACCT_NAME secAcctName,
T1.COUNTER_ID counterId, T11.TYPE_6 type6, T9.COUNTER_NAME counterName,
SUM(T15.PLEDGE_AMT) entrustAmt, SUM(T15.PLEDGE_AMT - NVL(T4.FINISHED_AMT, 0)) unfinishedAmt
DECODE(T2.ASSET_TYPE, #{PINAN_ASSET_TYPE_F01}, SUM(NVL(T1.ENTRUST_NUM * 100, 0)), #{PINAN_ASSET_TYPE_F10}, SUM(NVL(T1.ENTRUST_NUM * 100, 0)), SUM(NVL(T1.ENTRUST_AMT, T1.ENTRUST_NUM))) entrustAmt, DECODE(T2.ASSET_TYPE, #{PINAN_ASSET_TYPE_F01}, SUM(NVL(T1.ENTRUST_NUM * 100, 0) - NVL(T4.FINISHED_AMT * 100, 0)), #{PINAN_ASSET_TYPE_F10}, SUM(NVL(T1.ENTRUST_NUM * 100, 0) - NVL(T4.FINISHED_AMT * 100, 0)), SUM(NVL(T1.ENTRUST_AMT, T1.ENTRUST_NUM) - NVL(T4.FINISHED_AMT, 0))) unfinishedAmt
FROM ETR_ENTRUST T1 LEFT JOIN ETR_ENTRUST_ADD T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN(SELECT ENTRUST_ID,SUM(FINISH_AMT) AS FINISHED_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T4 ON T1.ENTRUST_ID = T4.ENTRUST_ID LEFT JOIN ETR_DISTRIBUTE T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID
LEFT JOIN FIN_PRODUCT_TYPE T11 ON T1.FINPROD_ID = T11.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO T8 ON T8.SEC_ACCT_ID = T2.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT T17 ON T17.FINPROD_ID = T1.CHL_ID
LEFT JOIN FIN_PRODUCT_TYPE T11 ON T1.FINPROD_ID = T11.FINPROD_ID
LEFT JOIN FIN_PRODUCT_TYPE T11 ON T1.FINPROD_ID = T11.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO T8 ON T8.SEC_ACCT_ID = T2.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT_CONVERTIBLE T12 ON T3.FINPROD_ID = T12.FINPROD_ID LEFT JOIN FIN_PRODUCT T13 ON T12.CON_FINPROD_ID = T13.FINPROD_ID LEFT JOIN FIN_PRODUCT T17 ON T17.FINPROD_ID = T1.CHL_ID
LEFT JOIN STL_SEC_ACCT_INFO T8 ON T8.SEC_ACCT_ID = T2.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT_TYPE T11 ON T1.FINPROD_ID = T11.FINPROD_ID LEFT JOIN FIN_PRODUCT T17 ON T17.FINPROD_ID = T1.CHL_ID
LEFT JOIN FIN_PRODUCT T10 ON T1.CHL_ID = T10.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T11 ON T1.FINPROD_ID = T11.FINPROD_ID
LEFT JOIN FIN_PRODUCT_TYPE T11 ON T1.FINPROD_ID = T11.FINPROD_ID
LEFT JOIN (
) T15 ON T15.ENTRUST_ID = T1.ENTRUST_ID
LEFT JOIN MST_CALENDAR_INFO T14 ON T1.CALENDAR_ID = T14.CALENDAR_ID
LEFT JOIN FIN_PRODUCT_ADD T7 ON T1.FINPROD_ID = T7.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO T8 ON T8.SEC_ACCT_ID = T2.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT T17 ON T17.FINPROD_ID = T1.CHL_ID
LEFT JOIN MST_COUNTER_PARTY T9 ON T1.COUNTER_ID = T9.COUNTER_ID LEFT JOIN FIN_PRODUCT_TYPE T11 ON T1.FINPROD_ID = T11.FINPROD_ID
INNER JOIN DATA_AUTH_NOTIFY_INST dani ON dani.BUSINESS_ID = T1.PORTFOLIO_ID AND dani.INSTITUTION_CODE IN
#{item}
AND dani.MODEL_TYPE = '02' AND dani.DATA_TYPE = 'PTL01'
T1.ENTRUST_CLASS= #{ENTRUST_CLASS_01} AND T5.TRADER = #{user} AND T1.ENTRUST_STATUS = #{entrustStatus} AND (T2.ENTRUST_CREATE_SOURCE is null or T2.ENTRUST_CREATE_SOURCE != '02')
AND T2.ASSET_TYPE = #{assetType}
AND (T11.TYPE_6 = #{TYPE6_B14} OR T11.TYPE_6 = #{TYPE6_B15}) AND T1.PS = #{PS_T04}
AND (T11.TYPE_6 = #{TYPE6_B14} OR T11.TYPE_6 = #{TYPE6_B15}) AND T1.PS = #{PS_T49}
AND DECODE(T15.PLEDGE_FINPROD, NULL, '01', T15.PLEDGE_FINPROD) = #{pledgeFinprod}
AND (T3.FINPROD_ID LIKE CONCAT('%',CONCAT(#{finprodId},'%')) OR T3.FINPROD_MARKET_ID LIKE CONCAT('%',CONCAT(#{finprodId},'%')) OR T3.FINPROD_ABBR LIKE CONCAT('%',CONCAT(#{finprodId},'%')))
AND T11.TYPE_6 IN(
#{item}
)
AND T11.TYPE_7 IN(
#{item}
)
AND T1.PS = #{ps}
AND T2.BUSI_PS = #{busiPs}
AND T1.TRADE_MARKET = #{tradeMarket}
AND T1.TRADE_PLAT = #{tradePlat}
AND T2.DEAL_MODE = #{dealMode}
AND T7.BOARD = #{board}
AND T2.PURCH_MODLE = #{purchModle}
AND T2.PURCH_TYPE = #{purchType}
AND T2.SEC_ACCT_ID = #{secAcctId}
AND T2.ASSET_TYPE1 = #{repoType}
AND T2.ASSET_TYPE1 = #{bankLendingType}
GROUP BY T1.CCY ,T1.CHL_ID /* add by songyawei */
, T2.ASSET_TYPE, T3.FINPROD_ID, T3.FINPROD_MARKET_ID, T3.FINPROD_ABBR, T1.TRADE_MARKET
, T2.PURCH_MODLE ,T2.PURCH_TYPE ,T2.SEC_ACCT_ID, T8.SEC_ACCT_NAME, T1.CHL_ID, T17.FINPROD_ABBR
, T2.SEC_ACCT_ID, T8.SEC_ACCT_NAME, T13.FINPROD_MARKET_ID, T13.FINPROD_NAME ,T12.CON_SHARE_ID, T1.CHL_ID, T17.FINPROD_ABBR
, T1.PS, T2.SEC_ACCT_ID, T8.SEC_ACCT_NAME, T11.TYPE_6, T1.CHL_ID, T17.FINPROD_ABBR
, T1.PS, T11.TYPE_6, T1.CHL_ID, T10.FINPROD_ABBR
, T1.PS, T11.TYPE_6
, T1.PS, T1.TRADE_MARKET, T2.ASSET_TYPE1, T2.TERM_DAYS, T2.SETTLE_SPREED, T15.PLEDGE_FINPROD
, T2.ASSET_TYPE, T2.BUSI_PS, T1.CALENDAR_ID, T14.CALENDAR_NAME, T2.ASSET_TYPE1, T2.TERM_DAYS
, T1.PS, T7.BOARD, T2.SEC_ACCT_ID, T8.SEC_ACCT_NAME, T1.CHL_ID, T17.FINPROD_ABBR
, T1.COUNTER_ID, T9.COUNTER_NAME, T11.TYPE_6

SELECT 
    T1.ENTRUST_ID entrustId, 
    T1.VDATE vdate, 
    T1.MDATE mdate, 

    T1.PORTFOLIO_ID portfolioId, 


    T1.INV_AIM invAim, T1.PRICE price, T2.MATURE_YIELD * 100 matureYield,
    T2.EXER_YIELD * 100 exerYield,T2.SETTLE_SPREED settleSpreed,T7.FINPROD_ID finprodId,
    T7.VDATE finvdate,T1.TRADE_MARKET_MODE,


    T1.PRICE_MODEL priceModel,
    T1.PS ps,


    T1.PRICE * 100 price, 
    T2.FIRST_UNIT_CPRICE firstPrice,
    T2.FIRST_UNIT_CPRICE2 firstPrice2,

    DECODE(T2.ASSET_TYPE,#{PINAN_ASSET_TYPE_F01},NVL(T1.ENTRUST_NUM * 100,0),#{PINAN_ASSET_TYPE_F10},NVL(T1.ENTRUST_NUM * 100,0),
      NVL(T1.ENTRUST_AMT,T1.ENTRUST_NUM)) entrustAmt,
    DECODE(T2.ASSET_TYPE,#{PINAN_ASSET_TYPE_F01},NVL(T3.FINISHED_AMT * 100,0),#{PINAN_ASSET_TYPE_F10},NVL(T3.FINISHED_AMT *
      100,0),NVL(T3.FINISHED_AMT,0)) finishedAmt,
    DECODE(T2.ASSET_TYPE,#{PINAN_ASSET_TYPE_F01},NVL(T1.ENTRUST_NUM * 100,0),#{PINAN_ASSET_TYPE_F10},NVL(T1.ENTRUST_NUM * 100,0),
      NVL(T1.ENTRUST_AMT,T1.ENTRUST_NUM))-DECODE(T2.ASSET_TYPE,#{PINAN_ASSET_TYPE_F01},NVL(T3.FINISHED_AMT * 100,0),
      #{PINAN_ASSET_TYPE_F10}, NVL(T3.FINISHED_AMT * 100,0),NVL(T3.FINISHED_AMT,0)) unfinishedAmt,　
    T2.SEC_ACCT_ID secAcctId, 
    T1.INV_MANAGER_ID invManagerId, 
    T6.SEC_ACCT_NAME SecAcctName,
    T1.REMARK remark,
    T2.MIN_AMT lowestDealNum
FROM ETR_ENTRUST　T1
LEFT JOIN ETR_ENTRUST_ADD T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID
LEFT JOIN (SELECT ENTRUST_ID,SUM(FINISH_AMT) AS FINISHED_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T3 ON T1.ENTRUST_ID = T3.ENTRUST_ID
LEFT JOIN ETR_DISTRIBUTE T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID
LEFT JOIN STL_SEC_ACCT_INFO T6 ON T6.SEC_ACCT_ID = T2.SEC_ACCT_ID

    LEFT JOIN FIN_PRODUCT T7 ON T1.FINPROD_ID = T7.FINPROD_ID



    T5.TRADER = #{user}
    AND T1.ENTRUST_STATUS = #{entrustStatus} 

        AND T1.FINPROD_ID = #{finprodId}


        AND T2.ASSET_TYPE = #{assetType} 


        AND T1.PS = #{ps}


        AND T1.TRADE_MARKET = #{tradeMarket}


        AND T1.TRADE_PLAT = #{tradePlat}


        AND NVL2(T2.SETTLE_SPREED, CONCAT('0',T2.SETTLE_SPREED+1), NULL) = #{settleSpeed}


        AND T2.SEC_ACCT_ID = #{secAcctId}


        AND T1.CHL_ID = #{chlId}



        AND T1.CHL_ID is null



        AND T2.DEAL_MODE = #{dealMode}


        AND T8.BOARD = #{board}


        AND T1.COUNTER_ID = #{counterId}


        AND T2.PURCH_MODLE = #{purchModle}


        AND T2.PURCH_TYPE = #{purchType}


        AND T2.ASSET_TYPE1 = #{repoType}


        AND T2.ASSET_TYPE1 = #{bankLendingType}


        AND T2.TERM_DAYS = #{termDays}


        AND DECODE(T11.PLEDGE_FINPRODS, NULL, '01', T11.PLEDGE_FINPRODS) LIKE CONCAT(CONCAT('%',#{pledgeFinprod}),'%')


        AND T1.CHL_ID IS NULL


order by T1.CREATE_TIME

SELECT 
    T1.ENTRUST_ID entrustId, 
    T1.VDATE vdate,
    decode(#{assetType},'Con1',T1.ENTRUST_DATE,T1.MDATE) mdate,
    T1.PORTFOLIO_ID portfolioId,/* add by songyawei */


    T1.INV_AIM invAim,


    T1.PRICE_MODEL priceModel,　
    T1.PS ps,


    T1.PRICE * 100 price, 


    T2.PURCH_MODLE purchModle,
    T2.PURCH_TYPE purchType,


    NVL(T2.ACT_NUM*100,0) holdetrPriceTotal,
    NVL(T10.AMOUNT*100,0) conetrPriceTotal,
    T1.ENTRUST_NUM*100 stocketrPriceTotal,


    T7.BID_PRICE bidPrice,


    NVL2(T2.SETTLE_SPREED, CONCAT('0',T2.SETTLE_SPREED+1), NULL) settleSpeed,

    DECODE(T2.ASSET_TYPE,#{PINAN_ASSET_TYPE_F01},NVL(T1.ENTRUST_NUM * 100,0),#{PINAN_ASSET_TYPE_F10},NVL(T1.ENTRUST_NUM * 100,0),
      NVL(T1.ENTRUST_AMT,T1.ENTRUST_NUM)) entrustAmt,
    DECODE(T2.ASSET_TYPE,#{PINAN_ASSET_TYPE_F01},NVL(T3.FINISHED_AMT * 100,0),#{PINAN_ASSET_TYPE_F10},NVL(T3.FINISHED_AMT *
      100,0),NVL(T3.FINISHED_AMT,0)) finishedAmt,
    DECODE(T2.ASSET_TYPE,#{PINAN_ASSET_TYPE_F01},NVL(T1.ENTRUST_NUM * 100,0),#{PINAN_ASSET_TYPE_F10},NVL(T1.ENTRUST_NUM * 100,0),
      NVL(T1.ENTRUST_AMT,T1.ENTRUST_NUM))-DECODE(T2.ASSET_TYPE,#{PINAN_ASSET_TYPE_F01},NVL(T3.FINISHED_AMT * 100,0),
      #{PINAN_ASSET_TYPE_F10}, NVL(T3.FINISHED_AMT * 100,0),NVL(T3.FINISHED_AMT,0)) unfinishedAmt,　
    T2.SEC_ACCT_ID secAcctId, 
    T1.INV_MANAGER_ID invManagerId, 
    T6.SEC_ACCT_NAME SecAcctName,
    T1.REMARK remark
FROM ETR_ENTRUST　T1
LEFT JOIN ETR_ENTRUST_ADD T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID
LEFT JOIN (SELECT ENTRUST_ID,SUM(FINISH_AMT) AS FINISHED_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T3 ON T1.ENTRUST_ID = T3.ENTRUST_ID
LEFT JOIN ETR_DISTRIBUTE T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID
LEFT JOIN STL_SEC_ACCT_INFO T6 ON T6.SEC_ACCT_ID = T2.SEC_ACCT_ID

    LEFT JOIN ETR_ENTRUST_BID_PRICE T7 ON T1.ENTRUST_ID = T7.ENTRUST_ID


    LEFT JOIN FIN_PRODUCT_ADD T8 ON T1.FINPROD_ID = T8.FINPROD_ID


    LEFT JOIN FIN_PRODUCT_TYPE T9 ON T1.FINPROD_ID = T9.FINPROD_ID


    LEFT JOIN (SELECT 
            PORTFOLIO_ID, 
            AMOUNT
        FROM ETR_SEC_POSITION 
        WHERE HODING_TYPE = #{POSITION_TYPE_E01} 
        AND CDATE =  TO_DATE(#{sysDate},'yyyy-mm-dd')
        AND FINPROD_ID = #{finprodId}

        AND SEC_ACCT_ID = #{secAcctId}


        AND SEC_ACCT_ID = '999999'

    ) T10 ON T1.PORTFOLIO_ID = T10.PORTFOLIO_ID


    LEFT JOIN (
        SELECT 
            T1.ENTRUST_ID,
              LISTAGG(T1.PLEDGE_FINPROD, ',') WITHIN GROUP 
                  (ORDER BY T1.PLEDGE_FINPROD) PLEDGE_FINPRODS
        FROM (

        ) T1
        LEFT JOIN(SELECT ENTRUST_ID,SUM(FINISH_AMT) AS FINISHED_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID
        --WHERE T1.PLEDGE_AMT - NVL(T2.FINISHED_AMT, 0) > 0
        GROUP BY T1.ENTRUST_ID
    ) T11 ON T1.ENTRUST_ID = T11.ENTRUST_ID


    T5.TRADER = #{user}
    AND T1.ENTRUST_STATUS = #{entrustStatus} 

        AND T1.FINPROD_ID = #{finprodId}


        AND T2.ASSET_TYPE = #{assetType} 


        AND (T9.TYPE_6 = #{TYPE6_B14} OR T9.TYPE_6 = #{TYPE6_B15}) 
        AND T1.PS = #{PS_T04}


        AND (T9.TYPE_6 = #{TYPE6_B14} OR T9.TYPE_6 = #{TYPE6_B15}) 
        AND T1.PS = #{PS_T49}


        AND T1.PS = #{ps}


        AND T1.CALENDAR_ID = #{calendarId,jdbcType=VARCHAR}


        AND T1.CALENDAR_ID IS NULL


        AND T2.BUSI_PS = #{ps}


        AND T1.TRADE_MARKET = #{tradeMarket}


        AND T1.TRADE_PLAT = #{tradePlat}


        AND NVL2(T2.SETTLE_SPREED, CONCAT('0',T2.SETTLE_SPREED+1), NULL) = #{settleSpeed}


        AND T2.SEC_ACCT_ID = #{secAcctId}


        AND T1.CHL_ID = #{chlId}


        AND T2.DEAL_MODE = #{dealMode}


        AND T8.BOARD = #{board}


        AND T1.COUNTER_ID = #{counterId}


        AND T2.PURCH_MODLE = #{purchModle}


        AND T2.PURCH_TYPE = #{purchType}


        AND T2.ASSET_TYPE1 = #{repoType}


        AND T2.ASSET_TYPE1 = #{bankLendingType}


        AND T2.TERM_DAYS = #{termDays}


        AND DECODE(T11.PLEDGE_FINPRODS, NULL, '01', T11.PLEDGE_FINPRODS) LIKE CONCAT(CONCAT('%',#{pledgeFinprod}),'%')


        AND T2.SEC_ACCT_ID IS NULL


        AND T1.CHL_ID IS NULL


order by T1.CREATE_TIME

SELECT 
    T3.FINPROD_MARKET_ID finprodId,
    T3.FINPROD_ABBR finprodName,
    T5.TYPE_6 type6,
    T3.REGIST_ORG registOrg,
    T4.PORTFOLIO_ID portfolioId,
    T4.PORTFOLIO_NAME portfolioName,
    T2.PLEDGE_FACE_VALUE * T2.PLEDGE_NUMBER pledgeAmt,
    T2.PLEDGE_RATIO * 100 pledgeRatio
FROM ETR_ENTRUST T1
LEFT JOIN ETR_PLEDGE T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID
LEFT JOIN FIN_PRODUCT T3 ON T2.FINPROD_ID = T3.FINPROD_ID
LEFT JOIN PTL_PORTFOLIO T4 ON T1.PORTFOLIO_ID = T4.PORTFOLIO_ID
LEFT JOIN FIN_PRODUCT_TYPE T5 ON T3.FINPROD_ID = T5.FINPROD_ID
LEFT JOIN ETR_DISTRIBUTE T6 ON T1.ENTRUST_ID = T6.ENTRUST_ID
LEFT JOIN(

) T9 ON T9.FINPROD_ID = T2.FINPROD_ID
LEFT JOIN (
       SELECT 
           T1.ENTRUST_ID,
          T1.PLEDGE_FINPROD
    FROM (

    ) T1
    LEFT JOIN(SELECT ENTRUST_ID,SUM(FINISH_AMT) AS FINISHED_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID
    --WHERE T1.PLEDGE_AMT - NVL(T2.FINISHED_AMT, 0) > 0
) T7 ON T1.ENTRUST_ID = T7.ENTRUST_ID AND T7. PLEDGE_FINPROD = T9.PLEDGE_FINPROD
LEFT JOIN ETR_ENTRUST_ADD T8 ON T1.ENTRUST_ID = T8.ENTRUST_ID

    T6.TRADER = #{user}
    AND T1.PS = #{ps}
    AND T8.TERM_DAYS = #{termDays}
    AND T8.ASSET_TYPE1 = #{repoType}
    AND T1.TRADE_MARKET = #{tradeMarket}
    AND T1.ENTRUST_STATUS = #{entrustStatus}
    AND T7.PLEDGE_FINPROD = #{pledgeFinprod}
    AND NVL2(T8.SETTLE_SPREED, CONCAT('0',T8.SETTLE_SPREED+1), NULL) = #{settleSpeed}

